import { render, screen, fireEvent } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';

import { TooltipProvider } from '#/components/ui/tooltip';

import { AutomationContextMenu } from '../AutomationContextMenu';

vi.mock('#/utils/Styles/cn', () => ({
    cn: (...inputs: any[]) => inputs.filter(Boolean).join(' '),
}));

const renderWithTooltip = (ui: React.ReactElement) => {
    return render(<TooltipProvider>{ui}</TooltipProvider>);
};

describe('AutomationContextMenu', () => {
    const defaultProps = {
        x: 100,
        y: 100,
        beat: 4,
        section: null as any,
        points: [],
        onCurveSelect: vi.fn(),
        onShapeInsert: vi.fn(),
        onClose: vi.fn(),
    };

    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('should render correctly', () => {
        renderWithTooltip(<AutomationContextMenu {...defaultProps} />);
        expect(screen.getByText('Curve Type')).toBeInTheDocument();
        expect(screen.getByText('Insert Shape')).toBeInTheDocument();
    });

    it('should call onCurveSelect when curve option is clicked', () => {
        renderWithTooltip(<AutomationContextMenu {...defaultProps} />);
        const stepOption = screen.getByText(/Step/i);
        fireEvent.click(stepOption);
        expect(defaultProps.onCurveSelect).toHaveBeenCalledWith('step');
    });

    it('should call onShapeInsert when shape option is clicked', () => {
        renderWithTooltip(<AutomationContextMenu {...defaultProps} />);
        const sineOption = screen.getByText(/Sine/i);
        fireEvent.click(sineOption);
        expect(defaultProps.onShapeInsert).toHaveBeenCalledWith('sine');
    });

    it('should render all curve options', () => {
        renderWithTooltip(<AutomationContextMenu {...defaultProps} />);
        expect(screen.getByText('Linear')).toBeInTheDocument();
        expect(screen.getByText(/Step/i)).toBeInTheDocument();
        expect(screen.getAllByText(/Smooth/i).length).toBeGreaterThan(0);
        expect(screen.getByText('Exponential')).toBeInTheDocument();
    });

    it('should render all shape options', () => {
        renderWithTooltip(<AutomationContextMenu {...defaultProps} />);
        expect(screen.getByText(/Sine/i)).toBeInTheDocument();
        expect(screen.getByText(/Triangle/i)).toBeInTheDocument();
        expect(screen.getByText(/Sawtooth Up/i)).toBeInTheDocument();
        expect(screen.getByText(/Sawtooth Down/i)).toBeInTheDocument();
        expect(screen.getByText(/Square/i)).toBeInTheDocument();
        expect(screen.getByText(/Random/i)).toBeInTheDocument();
    });

    it('should only render shape section when section is "shape"', () => {
        renderWithTooltip(<AutomationContextMenu {...defaultProps} section="shape" />);
        expect(screen.queryByText('Curve Type')).not.toBeInTheDocument();
        expect(screen.getByText('Insert Shape')).toBeInTheDocument();
    });

    it('should only render curve section when section is "curve"', () => {
        renderWithTooltip(<AutomationContextMenu {...defaultProps} section="curve" />);
        expect(screen.getByText('Curve Type')).toBeInTheDocument();
        expect(screen.getByText('Insert Shape')).toBeInTheDocument();
    });

    it('should call onClose when background overlay is clicked', () => {
        renderWithTooltip(<AutomationContextMenu {...defaultProps} />);
        const overlay = document.body.querySelector('.fixed.inset-0');
        fireEvent.click(overlay!);
        expect(defaultProps.onClose).toHaveBeenCalled();
    });
});

import { type ReactElement, useState } from 'react';

import { DawChooserCard } from '#/components/daw/DawChooserCard';
import { DawCompactCheckbox } from '#/components/daw/DawCompactCheckbox';
import { DawDialogBody } from '#/components/daw/DawDialogBody';
import { DawDialogFooter } from '#/components/daw/DawDialogFooter';
import { DawDialogSection } from '#/components/daw/DawDialogSection';
import { Stack, Row, Grid } from '#/components/layout';
import { Button } from '#/components/ui/button';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '#/components/ui/dialog';
import { type Track, type BounceOptions } from '#/modules/Arrangement';

type BounceOptionsDialogProps = {
    track: Track;
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onConfirm: (options: BounceOptions) => void;
};

export const BounceOptionsDialog = ({
    track,
    open,
    onOpenChange,
    onConfirm,
}: BounceOptionsDialogProps): ReactElement => {
    const [options, setOptions] = useState<BounceOptions>({
        includeInserts: true,
        includeSends: false,
        includeAutomation: true,
        normalization: 'protection',
        tailHandling: 'auto',
        destination: 'new-track',
    });

    const handleConfirm = () => {
        onConfirm(options);
        onOpenChange(false);
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent className="max-w-md p-0 overflow-hidden border-none bg-surface-dialog shadow-2xl">
                <DialogHeader className="p-6 pb-0">
                    <DialogTitle className="text-xl font-bold tracking-tight text-foreground/95">
                        Bounce {track.name}
                    </DialogTitle>
                    <DialogDescription className="text-sm text-muted-foreground/80 mt-1.5 leading-relaxed">
                        Render this track to a high-quality audio clip.
                    </DialogDescription>
                </DialogHeader>

                <DawDialogBody className="p-6 pt-4 space-y-6">
                    {/* Destination Choice */}
                    <DawDialogSection title="Destination">
                        <Grid cols={2} gap={2}>
                            <DawChooserCard
                                compact
                                title="New Track"
                                description="Create a fresh audio track"
                                active={options.destination === 'new-track'}
                                onClick={() => setOptions({ ...options, destination: 'new-track' })}
                            />
                            <DawChooserCard
                                compact
                                title="Replace"
                                description="In-place replacement"
                                active={options.destination === 'replace'}
                                onClick={() => setOptions({ ...options, destination: 'replace' })}
                            />
                        </Grid>
                    </DawDialogSection>

                    {/* Rendering Depth */}
                    <DawDialogSection title="Signal Chain">
                        <Stack gap={3}>
                            <Row gap={3} as="label" className="cursor-pointer group">
                                <DawCompactCheckbox
                                    checked={options.includeInserts}
                                    onChange={(event) =>
                                        setOptions({ ...options, includeInserts: event.target.checked })
                                    }
                                />
                                <Stack gap={0.5}>
                                    <span className="text-[11px] font-medium text-foreground group-hover:text-primary transition-colors">
                                        Include Inserts
                                    </span>
                                    <span className="text-[9px] text-muted-foreground/60 leading-tight">
                                        Bake all plugins into the audio
                                    </span>
                                </Stack>
                            </Row>

                            <Row gap={3} as="label" className="cursor-pointer group">
                                <DawCompactCheckbox
                                    checked={options.includeSends}
                                    onChange={(event) => setOptions({ ...options, includeSends: event.target.checked })}
                                />
                                <Stack gap={0.5}>
                                    <span className="text-[11px] font-medium text-foreground group-hover:text-primary transition-colors">
                                        Include Sends
                                    </span>
                                    <span className="text-[9px] text-muted-foreground/60 leading-tight">
                                        Capture return effects (reverb, delay)
                                    </span>
                                </Stack>
                            </Row>

                            <Row gap={3} as="label" className="cursor-pointer group">
                                <DawCompactCheckbox
                                    checked={options.includeAutomation}
                                    onChange={(event) =>
                                        setOptions({ ...options, includeAutomation: event.target.checked })
                                    }
                                />
                                <Stack gap={0.5}>
                                    <span className="text-[11px] font-medium text-foreground group-hover:text-primary transition-colors">
                                        Include Automation
                                    </span>
                                    <span className="text-[9px] text-muted-foreground/60 leading-tight">
                                        Commit volume and pan movements
                                    </span>
                                </Stack>
                            </Row>
                        </Stack>
                    </DawDialogSection>

                    {/* Normalization & Tail */}
                    <Grid cols={2} gap={4}>
                        <DawDialogSection title="Normalization">
                            <select
                                className="w-full bg-surface-inset border border-border/30 rounded px-2 py-1 text-[11px] text-foreground focus:outline-none focus:ring-1 focus:ring-primary/40"
                                value={options.normalization}
                                onChange={(event) =>
                                    setOptions({ ...options, normalization: event.target.value as any })
                                }
                            >
                                <option value="off">Off</option>
                                <option value="protection">Peak Protection</option>
                                <option value="full">Full Normalize</option>
                            </select>
                        </DawDialogSection>

                        <DawDialogSection title="Tail Handling">
                            <select
                                className="w-full bg-surface-inset border border-border/30 rounded px-2 py-1 text-[11px] text-foreground focus:outline-none focus:ring-1 focus:ring-primary/40"
                                value={options.tailHandling}
                                onChange={(event) =>
                                    setOptions({ ...options, tailHandling: event.target.value as any })
                                }
                            >
                                <option value="auto">Auto (Detect)</option>
                                <option value="manual">Fixed (5s)</option>
                                <option value="off">None (Strict)</option>
                            </select>
                        </DawDialogSection>
                    </Grid>
                </DawDialogBody>

                <DawDialogFooter align="end" className="bg-surface-base/80">
                    <Button variant="ghost" size="sm" onClick={() => onOpenChange(false)}>
                        Cancel
                    </Button>
                    <Button variant="default" size="sm" onClick={handleConfirm}>
                        Render
                    </Button>
                </DawDialogFooter>
            </DialogContent>
        </Dialog>
    );
};

