                                            </option>
                                        ))}
                                    </DawCompactSelect>
                                </div>
                                {renderIife_14()}
                            </div>
                        );
                    }
                }
            };

            return (
                <DawPluginSectionCard
                    title="Vocals"
                    detail={<Mic className="size-3 text-[var(--color-accent-peach)]" aria-hidden="true" />}
                    detailMode="badge"
